head.script:
// 담당 범위 : inputType='text' 인 dataType='date' / 'time' Column 의 ioFormat (마스크 문자, 미설정 기본값, 길이 불일치)
//  - inputType='calendar' Column 관련 항목(calendarValueType 기본 포맷, 팝업/직접 입력, config.xml dataType)은 column_P_ioFormat_2.xml 담당
//  - "Body Column 에서만 동작하며 다른 영역의 Column 에 설정 시 무시됩니다." 는 validation 에서 제외 (column 샘플 관례, 설정 영역 con 옵션 미생성, Body Column 에만 설정)



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > ioFormat]<br/>dataType='date','time' 인 Column 의 날짜/시간 데이터 포맷을 마스크 문자로 설정합니다.",
    "validation" : [
        "dataType='date' 인 Column 은 'yyyy', 'MM', 'dd', 'HH', 'mm', 'SS' 마스크 문자를 사용하여 Cell 값의 포맷을 설정합니다.",
        "dataType='time' 인 Column 은 'HH', 'mm', 'ss' 마스크 문자를 사용하여 Cell 값의 포맷을 설정합니다.",
        "속성값을 설정하지 않으면 dataType='date' 인 Column 은 'yyyyMMdd', dataType='time' 인 Column 은 'HHmmss' 가 적용됩니다.",
        "dataType='date' 인 Column 에서 Cell 값의 길이가 ioFormat 속성값의 길이와 다르면 Cell 값이 그대로 표시됩니다."
    ]
}

// date Column 의 ioFormat 별 표시 포맷 (가이드 예시처럼 ioFormat 과 같은 단위로 표시, 목록에 없으면 기본 표시 포맷 yyyy-MM-dd)
scwin.dateDisplayFormat = {
    "yyyyMM" : "yyyy.MM",
    "yyyyMMddHHmmSS" : "yyyy-MM-dd HH:mm:SS"
};



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (date : ddMMyyyy, time : 미설정)
    con_ioFormat_date.setValue("ddMMyyyy");
    con_ioFormat_time.setValue("");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// ioFormat 형식으로 날짜/시간 값을 만든다 (2024-03-15 14:30:25)
scwin.makeValue = function (format) {
    return format.replace("yyyy", "2024").replace("MM", "03").replace("dd", "15")
        .replace("HH", "14").replace("mm", "30").replace("SS", "25").replace("ss", "25");
}



// comp 생성
//  - date : inputType='text', dataType='date', ioFormat = con_ioFormat_date (validation 1, 3, 4)
//  - time : inputType='text', dataType='time', ioFormat = con_ioFormat_time, displayFormat='HH:mm:ss' 고정 (validation 2, 3)
//  - 미설정은 속성 자체를 넣지 않는다
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] date Column 표시 포맷은 ioFormat 에 맞춰 고정 (yyyyMM -> yyyy.MM, yyyyMMddHHmmSS -> yyyy-MM-dd HH:mm:SS, 그 외는 기본 yyyy-MM-dd), time Column 은 HH:mm:ss\nRow 0 은 적용된 ioFormat 형식의 값 (미설정이면 yyyyMMdd / HHmmss 형식), Row 1 date 는 월을 한 자리로 넣은 7자리 값 2024315\n[절차] Cell 더블클릭 -> 편집 창의 값(ioFormat 형식)을 지우고 같은 형식으로 새 값 입력 (예: ddMMyyyy 이면 01052024) -> 결과창 클릭으로 편집 종료\n[확인] Target 생성 시와 편집 종료 시 저장값과 표시값 자동 출력"', '', 'label1');

    // 조건 설정 (자체 값 select -> getValue, 미설정은 속성 자체를 넣지 않는다)
    let cDateIoFormat = con_ioFormat_date.getValue();
    let cTimeIoFormat = con_ioFormat_time.getValue();
    let attrDate = '';
    if (cDateIoFormat !== '') {
        attrDate += ' ioFormat="' + cDateIoFormat + '"';
        if (scwin.dateDisplayFormat[cDateIoFormat]) {
            attrDate += ' displayFormat="' + scwin.dateDisplayFormat[cDateIoFormat] + '"';
        }
    }
    let attrTime = (cTimeIoFormat === '') ? '' : ' ioFormat="' + cTimeIoFormat + '"';

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 바인딩 dataList (body column id 와 동일한 컬럼 id 사용)
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="date" name="date" dataType="date"></w2:column>';
    strDlt += '<w2:column id="time" name="time" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // 이벤트 바인딩 (편집 종료 시 저장값 출력)
    let eList = $c.gcm.createEList(["onviewchange"]);

    // target 생성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + eList + ' dataList="data:dlt_bind" checkAllType="false" defaultCellHeight="30" id="" style="width:560px;height:120px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="280" style="" inputType="text" id="column1" value="date (dataType=date)"></w2:column>';
    strTarget += '<w2:column width="280" style="" inputType="text" id="column2" value="time (dataType=time)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="280" style="" inputType="text" dataType="date" id="date" value=""' + attrDate + '></w2:column>';
    strTarget += '<w2:column width="280" style="" inputType="text" dataType="time" displayFormat="HH:mm:ss" id="time" value=""' + attrTime + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 적용된 ioFormat 형식으로 데이터 설정 (미설정이면 가이드 기본값 형식)
    let dateFormat = cDateIoFormat || "yyyyMMdd";
    let timeFormat = cTimeIoFormat || "HHmmss";
    dlt_bind.setJSON([
        { "date" : scwin.makeValue(dateFormat), "time" : scwin.makeValue(timeFormat) },
        { "date" : "2024315", "time" : scwin.makeValue(timeFormat).replace("14", "09").replace("30", "05") }
    ], false);

    // validation 1, 3, 4 : date Column 저장값과 표시값
    wf_body_bottom.getObj("scwin").setReturnValue("date : ioFormat '" + target1.getColumnOption("date", "ioFormat") + "'"
        + " -> Row 0 '" + dlt_bind.getCellData(0, "date") + "' 표시 '" + target1.getCellDisplayData(0, "date") + "'"
        + " / Row 1 '" + dlt_bind.getCellData(1, "date") + "' 표시 '" + target1.getCellDisplayData(1, "date") + "'");
    // validation 2, 3 : time Column 저장값과 표시값
    wf_body_bottom.getObj("scwin").setReturnValue("time : ioFormat '" + target1.getColumnOption("time", "ioFormat") + "'"
        + " -> Row 0 '" + dlt_bind.getCellData(0, "time") + "' 표시 '" + target1.getCellDisplayData(0, "time") + "'"
        + " / Row 1 '" + dlt_bind.getCellData(1, "time") + "' 표시 '" + target1.getCellDisplayData(1, "time") + "'");
}



// validation 1 ~ 4 판정 출력 : 편집 종료 시 저장값(DataList)과 표시값
scwin.target1_onviewchange = function (info) {
    let colId = target1.getColumnID(info.colIndex);
    wf_body_bottom.getObj("scwin").setReturnValue("Row " + info.rowIndex + " / " + colId + " 편집 -> 저장값 '" + dlt_bind.getCellData(info.rowIndex, colId) + "'"
        + " 표시 '" + target1.getCellDisplayData(info.rowIndex, colId) + "'");
}
